import {createGymPassingAdapter,passingPartners} from '../gym/passing-adapter.js';
import * as THREE from 'three';
import {createPassingModel,PASS_PATTERNS} from './passing-model.js';
import {createPassingSession,fitPassingCamera} from './passing-session.js';
import {createPassingView} from './passing-view.js';
import {drawPass} from './learning-draw.js';
import {SPORT_SCENES,passClear} from './learning-model.js';
export const PASSING_BODY=`<div class="passing-layout"><div id="passing-court" class="passing-court" role="img" tabindex="0" aria-label="도름이와 친구가 실제로 공을 주고받는 운동장"><p id="passing-score" class="passing-score" role="status"></p></div><section id="passing-panel" class="passing-panel"><div class="passing-modes passing-partners" role="group" aria-label="함께 놀 친구"><button id="passing-rabbit" aria-pressed="true">토끼와</button><button id="passing-turtle" aria-pressed="false">거북이와</button></div><p id="passing-location" class="passing-help"></p><div class="passing-modes"><button id="passing-practice" aria-pressed="true">느긋한 연습</button><button id="passing-challenge" aria-pressed="false">다섯 번 도전</button></div><div class="passing-controls"><div class="passing-move" role="group" aria-label="도름이 직접 움직이기"><button id="passing-up" aria-label="운동장 안쪽으로 이동">↑</button><button id="passing-left" aria-label="왼쪽으로 이동">←</button><span>이동</span><button id="passing-right" aria-label="오른쪽으로 이동">→</button><button id="passing-down" aria-label="운동장 바깥쪽으로 이동">↓</button></div><div class="passing-aim"><label for="passing-yaw">방향 <output id="passing-yaw-value"></output></label><input id="passing-yaw" type="range" min="-35" max="35" step="1" value="8"><label for="passing-power">힘 <output id="passing-power-value"></output></label><input id="passing-power" type="range" min="0" max="100" step="1" value="42"></div></div><p id="passing-feedback" role="status"></p><div class="passing-actions"><button id="passing-launch" class="primary">패스하기</button><button id="passing-next">다음 공</button><button id="passing-pause">잠깐 쉬기</button><button id="passing-restart" hidden>다섯 번 다시</button></div><p class="passing-help">WASD · 방향 버튼으로 이동 / 패스한 뒤 금빛 원의 가운데로 가서 받아요. 조절 막대를 선택했을 때 방향키는 막대를 움직여요.</p><details id="passing-theory"><summary>더 보기 · 예전 패스 길 도해</summary><p>아래는 고정된 수비 구역과 직선 경로를 비교하는 그림이에요. 위 공놀이는 중력을 단순화한 게임 모형이에요.</p><canvas id="passing-diagram" width="720" height="400" aria-label="고정 수비와 친구 자리의 패스 길 비교"></canvas><div class="passing-theory-buttons"><button id="passing-slot-0">친구 1</button><button id="passing-slot-1">친구 2</button><button id="passing-slot-2">친구 3</button><button id="passing-scene">수비 바꾸기</button></div><p id="passing-theory-status"></p></details></section></div>`;
const KEYS={KeyW:'up',ArrowUp:'up',KeyS:'down',ArrowDown:'down',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right'},DIRECTIONS={left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]};
export function createPassingController({ui,getView,getActors,stage,isAllowed=()=>true,reduced=false,doc=globalThis.document,win=globalThis.window,sessionFactory=createPassingSession,viewFactory=createPassingView,fitCamera=fitPassingCamera}){
 const camera=new THREE.OrthographicCamera(-5,5,4,-4,.1,100),$=id=>doc.querySelector('#'+id);let live=null,mode='practice',partnerId='athletic-rabbit',generation=0;
 function listen(node,type,fn){if(!node)return;node.addEventListener(type,fn);live.listeners.push([node,type,fn]);}
 function movement(){if(!live)return;let x=0,z=0;for(const direction of new Set([...live.keys.values(),...live.pointers.values()])){x+=DIRECTIONS[direction][0];z+=DIRECTIONS[direction][1];}live.model.move(x,z);}
 function clearMove(){if(!live)return;live.keys.clear();live.pointers.clear();live.model.move(0,0);}
 function render(){if(!live)return;const s=live.model.snapshot(),partnerName=partnerId==='athletic-rabbit'?'토끼':'거북이';for(const [id,key]of[['passing-rabbit','athletic-rabbit'],['passing-turtle','athletic-turtle']]){$(id).setAttribute?.('aria-pressed',String(partnerId===key));$(id).hidden=!live.partners.includes(key);}$('passing-location').textContent=live.partners.includes('athletic-turtle')?'실내체육관의 열린 공놀이 공간이에요':'거북이는 운동장 북쪽 길의 실내체육관에 있어요. 나간 뒤 지도에서 실내체육관을 골라도 돼요';$('passing-score').textContent=`${PASS_PATTERNS[s.pattern].name} · ${mode==='challenge'?`주고받기 ${s.score} / 5 · ${s.attempts} / 5번 보냄`:`주고받기 ${s.score}번 · ${s.attempts}번 보냄`}`;
  for(const [id,key]of[['yaw','yawDeg'],['power','power']]){$('passing-'+id).value=String(s.settings[key]);$('passing-'+id).disabled=s.phase!=='aiming'||s.paused;$('passing-'+id+'-value').textContent=id==='power'?`${Math.round(s.settings.power)}%`:`${Math.round(s.settings.yawDeg)}°`;}
  $('passing-launch').disabled=s.phase!=='aiming'||s.paused;$('passing-next').disabled=s.phase!=='result'||s.paused||s.complete;$('passing-next').hidden=s.complete;$('passing-restart').hidden=!s.complete;$('passing-restart').disabled=s.paused;$('passing-pause').textContent=s.paused?'계속하기':'잠깐 쉬기';for(const choice of['practice','challenge'])$('passing-'+choice).setAttribute?.('aria-pressed',String(mode===choice));
  const prediction=live.prediction?.event?.type==='turtle-catch'?`초록 점선이 ${partnerName}의 손에 닿아요`:'점선 끝을 보고 위치·방향·힘을 조절해요';$('passing-feedback').textContent=s.paused?'멈췄어요. 계속하기를 누르면 이어져요':s.complete?`다섯 번 중 ${s.score}번 주고받았어요!`:s.phase==='aiming'?prediction:s.phase==='turtle-held'?`${partnerName}가 받았어요! 금빛 원에서 돌아오는 공을 기다려요`:s.phase==='return-flight'?'공이 돌아와요. 도름이를 움직여 받아요':s.reason;
  $('passing-court').setAttribute?.('aria-label',`${PASS_PATTERNS[s.pattern].name}. ${$('passing-feedback').textContent}`);
 }
 function observe(){if(!live)return;const s=live.model.snapshot();live.session.update(s,live.time,reduced);live.view.update(s,live.prediction);return s;}
 function preview(){if(!live)return;live.prediction=live.model.predict();live.fit=null;observe();render();}
 function pause(){if(!live)return;clearMove();live.model.pause();if(live.pointer)live.pointer.cancelled=true;render();}
 function clean(token,{restore=true}={}){if(!live||token!==generation)return;const old=live;clearMove();live=null;generation++;old.observer?.disconnect();for(const[node,type,fn]of old.listeners)node.removeEventListener(type,fn);try{old.model.dispose();old.view.dispose();}finally{old.session.dispose({restore});old.adapter?.dispose();stage.classList.remove('passing-open');doc.body?.classList.remove('passing-open');}}
 function close(){if(!live)return;const token=generation;clean(token);ui.close();}
 function open(nextPartner=partnerId){if(live||!isAllowed())return false;const source=getView();if(!source?.root)return false;const partners=passingPartners(source);if(!partners.length)return false;partnerId=partners.includes(nextPartner)?nextPartner:partners[0];const token=++generation;
  return ui.workshop((partnerId==='athletic-rabbit'?'토끼':'거북이')+'와 공 주고받기',PASSING_BODY,()=>{if(token!==generation||getView()!==source)return;let session,view,adapter;try{adapter=partners.length===1&&partners[0]==='athletic-turtle'?createGymPassingAdapter(source):null;const owning=adapter??source;session=sessionFactory({view:owning,zoneRoot:owning.root,...getActors(),partnerId});view=viewFactory(owning.root);
   const model=createPassingModel({mode,anchors:session.anchors,partnerName:partnerId==='athletic-rabbit'?'토끼':'거북이'});live={model,session,view,source,adapter,frame:owning.root,partners,listeners:[],keys:new Map(),pointers:new Map(),pointer:null,panelPointers:new Set(),prediction:null,previewClock:0,time:0,fit:null};stage.classList.add('passing-open');doc.body?.classList.add('passing-open');
   const act=(id,fn)=>listen($(id),'click',e=>{if(!live||token!==generation||e.detail>0&&live.pointer?.cancelled)return;e.preventDefault();fn();});
   for(const[id,choice]of[['passing-rabbit','athletic-rabbit'],['passing-turtle','athletic-turtle']])act(id,()=>{if(partnerId===choice||!live.partners.includes(choice))return;clearMove();const old=live.session;live.session={dispose(){},update(){}};old.dispose();try{live.session=sessionFactory({view:owning,zoneRoot:owning.root,...getActors(),partnerId:choice});live.model.dispose();live.model=createPassingModel({mode,anchors:live.session.anchors,partnerName:choice==='athletic-rabbit'?'토끼':'거북이'});partnerId=choice;live.time=0;live.pointer=null;$('passing-theory').open=false;const title=$('modal-title');if(title)title.textContent=(choice==='athletic-rabbit'?'토끼':'거북이')+'와 공 주고받기';preview();$('passing-court').focus();}catch{close();ui.toast('친구를 바꾸지 못했어요. 다시 열어 주세요');}});
   const launch=()=>{if(live.model.launch()){observe();render();}};act('passing-launch',launch);act('passing-next',()=>{if(live.model.next()){clearMove();preview();}});act('passing-restart',()=>{live.model.reset(mode);clearMove();preview();});
   for(const choice of['practice','challenge'])act('passing-'+choice,()=>{if(mode===choice)return;mode=choice;live.model.reset(mode);clearMove();preview();});
   act('passing-pause',()=>{if(doc.hidden)return;if(live.model.snapshot().paused){clearMove();live.model.resume();render();}else pause();});
   for(const[id,key]of[['yaw','yawDeg'],['power','power']])listen($('passing-'+id),'input',()=>{if(!live)return;live.model.aim({[key]:Number($('passing-'+id).value)});preview();});
   for(const direction of Object.keys(DIRECTIONS)){const node=$('passing-'+direction);listen(node,'pointerdown',e=>{if(!live||live.model.snapshot().paused||e.button!==0)return;e.preventDefault();node.setPointerCapture?.(e.pointerId);live.pointers.set(e.pointerId,direction);movement();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(node,type,e=>{live?.pointers.delete(e.pointerId);movement();});}
   listen(doc,'keydown',e=>{if(!live||e.ctrlKey||e.metaKey||e.altKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName)||$('passing-theory').open)return;const direction=KEYS[e.code];if(direction){e.preventDefault();if(e.repeat&&!live.keys.has(e.code))return;if(!live.model.snapshot().paused){live.keys.set(e.code,direction);movement();}}else if(e.code==='Space'&&e.target===$('passing-court')){e.preventDefault();if(!e.repeat)launch();}});listen(doc,'keyup',e=>{live?.keys.delete(e.code);movement();});
   const panel=$('passing-panel');listen(panel,'pointerdown',e=>{if(!live)return;live.panelPointers.add(e.pointerId);if(live.panelPointers.size>1&&live.pointer)live.pointer.cancelled=true;else live.pointer={id:e.pointerId,x:e.clientX,y:e.clientY,cancelled:e.isPrimary===false||e.button!==0};});listen(panel,'pointermove',e=>{const p=live?.pointer;if(p?.id===e.pointerId&&Math.hypot(e.clientX-p.x,e.clientY-p.y)>8)p.cancelled=true;});listen(panel,'pointercancel',e=>{if(!live)return;live.panelPointers.delete(e.pointerId);if(live.pointer)live.pointer.cancelled=true;});listen(panel,'pointerup',e=>live?.panelPointers.delete(e.pointerId));listen(panel,'keydown',e=>{if(e.repeat&&['Space','Enter'].includes(e.code))e.preventDefault();});
   listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});const resize=()=>{if(live)viewport(stage.clientWidth||320,stage.clientHeight||568);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('passing-court'));}
   let scene=0,slot=1;const diagram=()=>{const canvas=$('passing-diagram'),ctx=canvas?.getContext?.('2d');if(ctx)drawPass(ctx,{scene,slot,passed:true});const s=SPORT_SCENES[scene];$('passing-theory-status').textContent=passClear(s.passer,s.slots[slot],s.defenders)?'이 자리의 직선 길은 열려 있어요':'이 자리의 직선 길은 수비 구역과 겹쳐요';};listen($('passing-theory'),'toggle',()=>{if($('passing-theory').open){pause();diagram();}});for(let i=0;i<3;i++)act('passing-slot-'+i,()=>{slot=i;diagram();});act('passing-scene',()=>{scene=1-scene;diagram();});
   preview();resize();$('passing-court').focus();return()=>clean(token);
  }catch{if(live?.session===session)clean(token);else{try{view?.dispose();}finally{session?.dispose();adapter?.dispose();}}ui.close();ui.toast('함께 놀 준비를 못 했어요. 다시 열어 주세요');return;}
  },{kind:'passing-workshop',closeLabel:'나가기'});
 }
 function tick(dt){if(!live)return;if(getView()!==live.source){const token=generation;clean(token,{restore:false});ui.close();return;}const events=live.model.advance(dt);live.time+=dt;const s=live.model.snapshot();live.previewClock+=dt;if(s.phase==='aiming'&&live.previewClock>.075){live.previewClock=0;live.prediction=live.model.predict();live.fit=null;}observe();if(events.length||s.phase==='aiming')render();}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const box=$('passing-court').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,box.left-base.left),y=Math.max(0,box.top-base.top),rect={x,y,width:Math.max(1,Math.min(box.width,width-x)),height:Math.max(1,Math.min(box.height,height-y))},key=[x,y,rect.width,rect.height].join(',');if(key!==live.fit){fitCamera(camera,live.frame,rect,live.prediction?.points);live.fit=key;}return rect;}
 return{open,close,cancel:close,tick,pause,camera,viewport,get active(){return !!live;},snapshot:()=>live?{...live.model.snapshot(),turtleUUID:live.session.turtleUUID,partnerId}:null};
}
